package com.example.academic.evaluation;
import com.example.academic.schoolclass.SchoolClassService;import com.example.academic.enrollment.*;import com.example.academic.attendance.*;import com.example.academic.session.*;import com.example.academic.duration.*;import com.example.academic.security.*;import com.example.academic.common.*;import java.time.*;import java.util.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
@Service @RequiredArgsConstructor public class EvaluationContextService {
 private final SchoolClassService classes;private final EnrollmentRepository enrollments;private final EnrollmentPeriodRepository periods;private final ClassSessionRepository sessions;private final AttendanceRepository attendance;private final DurationProgressService duration;
 public record Period(LocalDate activeFrom,LocalDate activeUntil){}
 public record Learner(Long enrollmentId,Long studentId,String studentName,String studyStatus,List<Period> periods){}
 public record Session(Long id,LocalDate sessionDate,LocalTime startTime,LocalTime endTime,String status){}
 public record Mark(Long enrollmentId,Long sessionId,LocalDate sessionDate,String status,boolean hasPermission){}
 public record Context(Long classId,Long branchId,LocalDateTime observedAt,List<Learner> enrollments,List<Session> sessions,List<Mark> attendance,DurationDto.Progress duration){}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Context get(Long id,boolean includeAttendance){if(!Set.of(Role.SUPER_ADMIN,Role.ADMIN,Role.TEACHER).contains(Users.current().role()))throw ApiException.forbidden();var c=classes.require(id);var all=enrollments.findBySchoolClassId(id);Map<Long,List<Period>> byEnrollment=new HashMap<>();for(var p:periods.findByEnrollmentSchoolClassId(id))byEnrollment.computeIfAbsent(p.getEnrollment().getId(),k->new ArrayList<>()).add(new Period(p.getActiveFrom(),p.getActiveUntil()));var learners=all.stream().map(e->new Learner(e.getId(),e.getStudent().getId(),e.getStudent().getFullName(),e.getStudyStatus().name(),List.copyOf(byEnrollment.getOrDefault(e.getId(),List.of())))).toList();var sessionRows=includeAttendance?sessions.findBySchoolClassIdOrderBySessionDateAsc(id).stream().filter(s->s.getStatus()==ClassSession.Status.COMPLETED).map(s->new Session(s.getId(),s.getSessionDate(),s.getStartTime(),s.getEndTime(),s.getStatus().name())).toList():List.<Session>of();var marks=includeAttendance?attendance.evaluationMarks(id).stream().map(a->new Mark(a.getEnrollmentId(),a.getSessionId(),a.getSessionDate(),a.getStatus(),a.getHasPermission())).toList():List.<Mark>of();return new Context(id,c.getBranchId(),LocalDateTime.now(BusinessTime.ZONE),learners,sessionRows,marks,duration.get(id));}
}
